window.ScripturaLexicons.BDAG_PART_0296 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-01\" data-source=\"BDAG\" data-search=\"ποτίζω verbo dar de beber, dessedentar, regar, beber BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποτίζω</td><td>verbo</td><td>dar de beber, dessedentar, regar, beber</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-02\" data-source=\"BDAG\" data-search=\"Ποτίολοι, ων, οἱ nome próprio masculino plural Putéolos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ποτίολοι, ων, οἱ</td><td>nome próprio masculino plural</td><td>Putéolos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-03\" data-source=\"BDAG\" data-search=\"ποτόν, οῦ, τό substantivo neutro bebida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποτόν, οῦ, τό</td><td>substantivo neutro</td><td>bebida</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-04\" data-source=\"BDAG\" data-search=\"πότος, ου, ὁ substantivo masculino banquete, reunião para beber, orgia de bebida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πότος, ου, ὁ</td><td>substantivo masculino</td><td>banquete, reunião para beber, orgia de bebida</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-05\" data-source=\"BDAG\" data-search=\"ποῦ advérbio interrogativo onde?, aonde? BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποῦ</td><td>advérbio interrogativo</td><td>onde?, aonde?</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-06\" data-source=\"BDAG\" data-search=\"πού advérbio enclítico em algum lugar, aproximadamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πού</td><td>advérbio enclítico</td><td>em algum lugar, aproximadamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-07\" data-source=\"BDAG\" data-search=\"Πούδης, εντος, ὁ nome próprio masculino Pudente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πούδης, εντος, ὁ</td><td>nome próprio masculino</td><td>Pudente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-08\" data-source=\"BDAG\" data-search=\"πούς, ποδός, ὁ substantivo masculino pé, perna, unidade de comprimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πούς, ποδός, ὁ</td><td>substantivo masculino</td><td>pé, perna, unidade de comprimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-09\" data-source=\"BDAG\" data-search=\"πρᾶγμα, ατος, τό substantivo neutro ato, acontecimento, tarefa, assunto, litígio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρᾶγμα, ατος, τό</td><td>substantivo neutro</td><td>ato, acontecimento, tarefa, assunto, litígio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-10\" data-source=\"BDAG\" data-search=\"πραγματεία, ας, ἡ substantivo feminino atividade, ocupação, negócios BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πραγματεία, ας, ἡ</td><td>substantivo feminino</td><td>atividade, ocupação, negócios</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-11\" data-source=\"BDAG\" data-search=\"πραγματεύομαι verbo negociar, comerciar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πραγματεύομαι</td><td>verbo</td><td>negociar, comerciar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-12\" data-source=\"BDAG\" data-search=\"πραθείς, πραθῆναι remissão ver πιπράσκω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πραθείς, πραθῆναι</td><td>remissão</td><td>ver πιπράσκω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-13\" data-source=\"BDAG\" data-search=\"πραιτώριον, ου, τό substantivo neutro pretório, residência do governador, guarda pretoriana BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πραιτώριον, ου, τό</td><td>substantivo neutro</td><td>pretório, residência do governador, guarda pretoriana</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-14\" data-source=\"BDAG\" data-search=\"πραίφεκτος, ου, ὁ substantivo masculino prefeito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πραίφεκτος, ου, ὁ</td><td>substantivo masculino</td><td>prefeito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-15\" data-source=\"BDAG\" data-search=\"πράκτωρ, ορος, ὁ substantivo masculino oficial de justiça, cobrador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πράκτωρ, ορος, ὁ</td><td>substantivo masculino</td><td>oficial de justiça, cobrador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-16\" data-source=\"BDAG\" data-search=\"πρᾶξις, εως, ἡ substantivo feminino atividade, função, ação, ato, negócio, condição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρᾶξις, εως, ἡ</td><td>substantivo feminino</td><td>atividade, função, ação, ato, negócio, condição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-17\" data-source=\"BDAG\" data-search=\"πρᾶος remissão ver πραΰς BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρᾶος</td><td>remissão</td><td>ver πραΰς</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-18\" data-source=\"BDAG\" data-search=\"πραότης remissão ver πραΰτης BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πραότης</td><td>remissão</td><td>ver πραΰτης</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-19\" data-source=\"BDAG\" data-search=\"πρασιά, ᾶς, ἡ substantivo feminino canteiro, grupo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρασιά, ᾶς, ἡ</td><td>substantivo feminino</td><td>canteiro, grupo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0296-20\" data-source=\"BDAG\" data-search=\"πράσσω verbo fazer, realizar, praticar, cobrar, agir, estar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πράσσω</td><td>verbo</td><td>fazer, realizar, praticar, cobrar, agir, estar</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0296-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποτίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποτίζω</span> imperf. <span class=\"greek\">ἐπότιζον</span>; fut. <span class=\"greek\">ποτιῶ</span> LXX, e 3ª pess. sing. <span class=\"greek\">ποτίσει</span> Sir 15:3; 1º aor. <span class=\"greek\">ἐπότισα</span>; perf. <span class=\"greek\">πεπότικα</span>. Pass.: imperf. <span class=\"greek\">ἐποτιζόμην</span> B 7:3 (em Hs 9, 1, 8; 9, 25, 1 provavelmente méd., v. 2 abaixo); 1º fut. 3ª pess. sing. <span class=\"greek\">ποτισθήσεται</span> Ezk 32:6; 1º aor. <span class=\"greek\">ἐποτίσθην</span>; perf. part. <span class=\"greek\">πεποτισμένος</span> (<span class=\"greek\">ποτόν</span>, <span class=\"greek\">πότος</span>; Hippocr., X.+)</p><p class=\"entry-text\">① Possibilitar que alguém ou algo beba</p><p class=\"entry-text\">ⓐ Acerca de pessoas, dar de beber <span class=\"greek\">τινά</span> a alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:35</a>, 37, 42; 27:48; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:20</a> (Pr 25:21). Com duplo ac., fazer alguém beber algo, <span class=\"greek\">τινά</span> <span class=\"greek\">τι</span> <span class=\"greek\">π</span>. dar algo de beber a alguém (Pla., Phdr. 247e; Gen 19:32; Judg 4:19a; 1 Km 30:11 e outros; B-D-F §155, 7; Rob. 484), água (<span class=\"greek\">ποτίζειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">ποτήριον</span> como Jer 16:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:41</a>. <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλέγξεως</span> água de comprovação da culpa, em referência à prova pela água para revelar o pecado GJs 16:1; cf. 16:2. <span class=\"greek\">χολὴν</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">ὄξους</span> GPt 5:16; B 7:5. Em linguagem figurada <span class=\"greek\">π</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">γάλα</span> dar leite de beber a alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:2</a> (<span class=\"greek\">οὐ</span> <span class=\"greek\">βρῶμα</span> é acrescentado em zeugma; B-D-F §479, 2; Rob. 1200f). Em lugar do ac. de coisa temos <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:8</a> (em linguagem figurada). <span class=\"greek\">ἐπότιζεν</span> <span class=\"greek\">ῥήματι</span> (Paulo) deu a palavra de beber (a Artemila) AcPl Ha 4, 5. Pass., receber (algo) para beber, com dat. de coisa (para a voz ativa com dat. de coisa, v. OGI 200, 16; Cebes 5, 2; 3 Macc 5:2) <span class=\"greek\">ἐποτίζετο</span> <span class=\"greek\">ὄξει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">χολῇ</span> deram-lhe vinagre e fel para beber B 7:3. Também ac. de coisa (TestAbr A, ApcEsdr; B-D-F §159, 1; Rob. 485) em linguagem figurada (cf. p. ex. Sir 15:3; Is 29:10) <span class=\"greek\">πάντες</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἐποτίσθημεν</span> a todos nós foi dado beber do mesmo Espírito (ou fomos impregnados dele) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:13</a> (diferentemente GCuming NTS 27, ’81, 283–85, sob c).</p><p class=\"entry-text\">ⓑ Acerca de animais, dar de beber (Diod S 19, 94, 9; Polyaenus 6, 4, 2; OGI 483, 169; frequentemente na LXX) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:15</a>.</p><p class=\"entry-text\">ⓒ Acerca de plantas, regar (X., Symp. 2, 25 et al.; Ezk 17:7; Cleopatra linha 93 <span class=\"greek\">τ</span>. <span class=\"greek\">βοτάνας</span>. O sentido ‘irrigar’ um campo, jardim etc. é muito mais comum; frequentemente assim em papiros, LXX, OdeSol, JosAs) <span class=\"greek\">τὰς</span> <span class=\"greek\">ῥάβδους</span> as varas que foram plantadas Hs 8, 2, 9a. Pass. 8, 2, 9b (<span class=\"greek\">ὕδατι</span>); 8, 3, 8. GCuming (v. a acima) interpreta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:13</a> como ‘regar’ com o Espírito mediante a afusão batismal; resposta de ERogers, NTS 29, ’83, 139–42 (‘fazer beber’). Uso abs., na imagem da fundação de uma igreja, com <span class=\"greek\">φυτεύειν</span> (como Hs 8, 3, 8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:6</a>–8.</p><p class=\"entry-text\">② Proporcionar bebida a si mesmo, beber, voz méd. <span class=\"greek\">πᾶν</span> <span class=\"greek\">γένος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κτίσεως</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἐποτίζετο</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πηγῶν</span> Hs 9, 1, 8; cf. 9, 25, 1.—DELG s.v. <span class=\"greek\">πίνω</span> C 1. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ποτίολοι, ων, οἱ</h1><div class=\"entry-meta\"><span>nome próprio masculino plural</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ποτίολοι</span>, <span class=\"greek\">ων</span>, <span class=\"greek\">οἱ</span> (Strabo 5, 4, 6; Porphyr., Vi. Plot. 2; Jos., Ant. 18, 161, Vi. 16; inscrições [OGI II, índice p. 595]; sobre a grafia, v. B-D-F §41, 1; Mlt-H. 76), Putéolos, cidade altamente cosmopolita no golfo de Nápoles, na Itália, a 12 km de Nápoles. Paulo desembarcou ali em sua viagem a Roma e passou uma semana com os cristãos do lugar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:13</a>.—MRostovtzeff, The Social and Economic History of the Roman Empire2 ’57, II 610 n. 25 (referências); Hemer, Acts 155; Pauly-W. XXIII 2036–60; Kl. Pauly IV 1244f; DACL XIV 1673–87; BHHW III 1533; PECS 743f; Haenchen ad loc.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποτόν, οῦ, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποτόν</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">τό</span> (Hom.+; PSI 64, 21 [I a.C.]; PGiess 19, 6; LXX; TestSol 11: 7, 9 C; SibOr 3, 746; Philo; Jos., Bell. 3, 183, Ant. 1, 245f; Ar.; neut. substantivado de <span class=\"greek\">ποτός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span>=bebível), aquilo que se bebe, bebida, com <span class=\"greek\">τροφή</span> (alimento e) bebida (Longus 2, 7, 4; Jos., Ant. 7, 159) em geral D 10:3a, depois acerca da Eucaristia <span class=\"greek\">πνευματικὴ</span> <span class=\"greek\">τροφὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποτόν</span> 3b. Com <span class=\"greek\">βρωτόν</span> GJs 1:4. Pl. <span class=\"greek\">βρώματα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποτά</span> (<span class=\"greek\">βρῶμα</span> 1 e cf. PSI loc. cit. <span class=\"greek\">μήτε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ποτοῖς</span> <span class=\"greek\">μήτε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">βρωτοῖς</span>; EpArist 128 e outros) ITr 2:3. Também <span class=\"greek\">σιτία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποτά</span> (cf. Hdt. 5, 34, 1; X., An. 7, 1, 33; frequentemente em Philo) Dg 6:9.—DELG s.v. <span class=\"greek\">πίνω</span> C. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πότος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πότος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (X., Pla. et al.; Sb 7452, 21 [III d.C.?]; LXX; JosAs 21:6 [cód. A p. 71, 25 Bat.]; EpArist 262; Philo, Vi. Cont. 46; Jos., Ant. 5, 289; TestJud 8:2), reunião social em que se servia vinho, reunião para beber (X., Symp. 8, 41, como sinônimo de <span class=\"greek\">κλῆσις</span> ‘banquete’ 1, 7), pl. (Aristoph., Pla. et al.; Pr 23:30) com <span class=\"greek\">κῶμοι</span> (v. esse lema e Synes., Providence 1, 14 p. 107c) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:3</a> aqui provavelmente no sentido de ‘orgia de bebida’. No mundo greco-romano era costume dos letrados realizar banquetes em que se discutiam assuntos da atualidade, com os participantes bem regados a vinho (v. os diálogos de Pl. e especialmente X., Symp.). Estes não seriam adequadamente traduzidos por ‘orgias de bebida’. É provável que a passagem petrina tenha em vista participantes menos sofisticados.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποῦ</h1><div class=\"entry-meta\"><span>advérbio interrogativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποῦ</span> marcador interrog. de lugar (Hom.+).</p><p class=\"entry-text\">① Referência interrogativa a lugar sem sugestão de movimento, onde(?), em que lugar(?)</p><p class=\"entry-text\">ⓐ Em perguntas diretas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:2</a>; 26:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:12</a>, 14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:17</a>, 37; 22:9, 11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:38</a>; 7:11; 8:10, 19; 9:12; 11:34 e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:20</a>; IEph 18:1 (ambos Is 19:12); H 9, 11, 3; GJs 21:1, 2 (códices); 23:1a, 2. Em perguntas retóricas que esperam resposta negativa, onde está? (Il. 5, 171; Diod S 14, 67, 1 <span class=\"greek\">ποῦ</span> … ; <span class=\"greek\">ποῦ</span> … ; Lucian, Dial. Deor. 4, 4; TestJob 32:2ff; ApcEsdr 2:8 p. 28, 19 Tdf. e outros; papiros, LXX; Jos., Ant. 10, 156 e outros; Ath., R. 21 p. 74, 16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:20abc</a> (<span class=\"greek\">ποῦ</span> em várias perguntas diretas consecutivas como Libanius, Or. 61 p. 337, 18 F.); 12:17ab, 19; 15:55ab (Hos 13:14ab); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:18</a> (Pr 11:31); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:4</a>.</p><p class=\"entry-text\">ⓑ Em perguntas indiretas em lugar de <span class=\"greek\">ὅπου</span>, seguido de indic. (En 12:1b; ParJer 7:14) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:47</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:39</a>; 11:57; 20:2, 13, 15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:13</a>; 1 Cl 40:3; GJs 23:1. Seguido de subj.: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ποῦ</span> (Epict. 2, 4, 7) não ter lugar, não ter onde <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.58\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:58</a>; 12:17. <span class=\"greek\">ποῦ</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἀποκρύψῃ</span> onde (Isabel) poderia esconder (João) GJs 22:3.</p><p class=\"entry-text\">② Referência interrogativa a lugar com implicação de movimento (em lugar de <span class=\"greek\">ποῖ</span> [v. esse lema], que não se encontra no grego bíblico), onde(?), aonde(?), para que lugar(?) (Antiphon 2, 4, 8; X., Cyr. 1, 2, 16; Epict. [índice Sch.]; Vett. Val. 137, 35; 341, 6; Alciphron 4, 13, 2; Gen 16:8; Judg 19:17; Jdth 10:12; 1 Macc 3:50; En, JosAs, ParJer, ApcMos—Kühner-G. I 545, 4; B-D-F §103; Rob. 298; AMaidhof, Z. Begriffsbestimmung der Koine: Beiträge zur histor. Syntax der Griech. Sprache 20, 1912, 298ff).</p><p class=\"entry-text\">ⓐ Em perguntas diretas (Cebes 6, 2; 20, 1; En 102:1; JosAs 6:2f; GrBar 9:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:35</a>; 13:36; 16:5 (cf. o amuleto de um politeísta em ABarb, Der Österreich. Limes XVI 54f <span class=\"greek\">ποῦ</span> <span class=\"greek\">ὑπάγεις</span>; também Rtzst., ARW 24, 1926, 176–78); 1 Cl 28:2, 3 (Ps 138:7), 4. <span class=\"greek\">ποῦ</span> <span class=\"greek\">σε</span> <span class=\"greek\">ἀπάξω</span> aonde devo levar-te? GJs <span class=\"greek\">ποῦ</span> <span class=\"greek\">πορεύῃ</span> 19:1 (códices).</p><p class=\"entry-text\">ⓑ Em perguntas indiretas (En 12:1a; ParJer 5:13; ApcMos 42) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:8</a>; 8:14ab; 12:35; 14:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:11</a>; IPhld 7:1; Hm 12, 5, 4.—DELG s.v. <span class=\"greek\">πο</span>-. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πού</h1><div class=\"entry-meta\"><span>advérbio enclítico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πού</span> adv. enclítico (Hom.+; papiros, LXX; TestSol 1, 46; Just.; Tat. 37, 1; Mel., P. 72, 530.)</p><p class=\"entry-text\">① Marcador de posição ou lugar indeterminado, em algum lugar, com citações (Diod S 1, 12, 10 ‘o poeta’ [=Homero] diz <span class=\"greek\">ποὺ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ποίησιν</span>=em algum lugar de seu poema. Acerca de Cercidas [III a.C.] [ed. Diehl3 Fgm. 11a, 4] <span class=\"greek\">ὀρθῶς</span> <span class=\"greek\">λέγει</span> <span class=\"greek\">που</span> <span class=\"greek\">Κερκίδας</span> [segue-se uma citação]. Lucian, Ver. Hist. 2, 42 <span class=\"greek\">φησὶ</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">που</span> <span class=\"greek\">κἀκεῖνος</span> [isto é, Antímaco IV a.C.], depois uma citação; Appian, Bell. Civ. 1, 97 §452 [com uma citação]; Plut., Mor. 553b [citação homérica]; Philo, Ebr. 61 <span class=\"greek\">εἶπε</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">πού</span> <span class=\"greek\">τις</span>, e segue-se Gen 20:12; Just. A I, 3, 3 <span class=\"greek\">ἔφη</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">που</span> <span class=\"greek\">καί</span> <span class=\"greek\">τις</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:6</a>; 4:4; 1 Cl 15:2; 21:2; 26:2; 28:2; 42:5.—Depois de uma negativa=em nenhum lugar Dg 5:2. Com enfraquecimento do sentido local <span class=\"greek\">εἰ</span> <span class=\"greek\">δέ</span> <span class=\"greek\">που</span> <span class=\"greek\">παρηκολουθώς</span> <span class=\"greek\">τις</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πρεσβυτέροις</span> <span class=\"greek\">ἔλθοι</span> quando porventura vinha alguém que havia estado em contato com os ‘presbíteros’ Papias (2:4).</p><p class=\"entry-text\">② Marcador de aproximação numérica, cerca de, aproximadamente (Paus. 8, 11, 14 <span class=\"greek\">περὶ</span> <span class=\"greek\">εἴκοσί</span> <span class=\"greek\">που</span> <span class=\"greek\">σταδίους</span>; Aelian, VH 13, 4; Jos., C. Ap. 1, 104) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:19</a>.—Sobre <span class=\"greek\">δή</span> <span class=\"greek\">π</span>., <span class=\"greek\">μή</span> <span class=\"greek\">π</span>., v. <span class=\"greek\">δήπου</span>, <span class=\"greek\">μήπου</span>.—<span class=\"greek\">μή</span> <span class=\"greek\">που</span> (algumas edd. <span class=\"greek\">μήπου</span>; v.l. <span class=\"greek\">μήπως</span>. Hom. et al.; BGU 446, 15; Jos., Bell. 7, 397, Ant. 18, 183) conj., para que não, <span class=\"greek\">φοβεῖσθαι</span> <span class=\"greek\">μ</span>. <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:29</a>.—DELG s.v. <span class=\"greek\">πο</span>-. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πούδης, εντος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πούδης</span>, <span class=\"greek\">εντος</span>, <span class=\"greek\">ὁ</span> (BGU 455, 4 [I d.C.] e outros em papiros; Jos., Bell. 6, 172), Pudente, nome pessoal romano (o n perdeu-se, como em inscrições romanas, porque era nasalizado na pronúncia: B-D-F §41, 2; 54;; v. Mlt-H. 134). Cristão de resto desconhecido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:21</a> (a identificação com o marido de Cláudia mencionado em CIL VI 15066 é incerta).—Lghtf., St. Clement I 1890, 76ff; GEdmundson, The Church in Rome 1913, 244–49; Kl. Pauly IV 1240. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πούς, ποδός, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πούς</span>, <span class=\"greek\">ποδός</span>, <span class=\"greek\">ὁ</span> (Hom.+ ‘pé’ em vários sentidos)</p><p class=\"entry-text\">① Pé, de pessoas ou (raramente em nossa literatura) animais, ou das estranhas criaturas de Rv</p><p class=\"entry-text\">ⓐ Com foco em uma parte do corpo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:6</a> (Ps 90:12); 7:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:45ab</a> e outros. Com <span class=\"greek\">κεφαλή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:21</a>; 1 Cl 37:5ab. Com <span class=\"greek\">χείρ</span> ou <span class=\"greek\">χεῖρες</span> (Ps 21:17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:8ab</a>; 22:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:39</a>, 40 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:15</a> (quanto à reflexão acerca do pé e da mão, relativamente à sua relação com o corpo inteiro, cf. Epict. 2, 10, 4). <span class=\"greek\">ὑποδήσασθαι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">π</span>. calçar os pés <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:15</a> (em linguagem figurada vívida). Acerca de ouvintes e discípulos <span class=\"greek\">καθῆσθαι</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">π</span>. <span class=\"greek\">τινός</span> sentar-se aos pés de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:35</a>; cf. 10:39. Com sentido não literal <span class=\"greek\">ἀνατεθραμμένος</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">Γαμαλιήλ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:3</a> (escol. sobre Pla. 467b <span class=\"greek\">παρὰ</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Σωκράτους</span>). Com imagem parcialmente figurada (Synes., Ep. 17 p. 175c <span class=\"greek\">παρὰ</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">ἀποδίδως</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χάριν</span>) <span class=\"greek\">ἐτίθουν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀποστόλων</span> 4:35; cf. v. 37; 5:2. <span class=\"greek\">πίπτειν</span> (v. esse lema 1b<span class=\"greek\">α</span>ב) <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">τινός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:29</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:32</a> v.l.; <span class=\"greek\">ἔμπροσθεν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ποδῶν</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:10</a>; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:25</a>; <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">π</span>. <span class=\"greek\">τινός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:41</a>; 17:16. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">π</span>. <span class=\"greek\">τινός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:22</a>; 7:25 (<span class=\"greek\">προσπίπτειν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">κτλ</span>.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:10</a>; 10:25 D (o gen. é facilmente suprido); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:17</a>; Hv 3, 2, 3. <span class=\"greek\">προσπίπτειν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">π</span>. <span class=\"greek\">τινί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:29</a> D. <span class=\"greek\">προσκυνεῖν</span> <span class=\"greek\">ἐνώπιον</span> (ou <span class=\"greek\">ἔμπροσθεν</span>) <span class=\"greek\">τῶν</span> <span class=\"greek\">ποδῶν</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:9</a>; 22:8. Lavar os pés, como expressão de hospitalidade ou humildade (Gen 18:4; 19:2; TestAbr A 3 p. 80, 2 [Stone p. 8]; B 3 p. 107, 21 [St. p. 62] e outros; JosAs 7:1): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:5f</a>, 8–10, 12, 14ab (cf. <span class=\"greek\">λούω</span> 2a); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:10</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:44a</a>.—V. HAlmqvist, Plutarch u. d. NT ’46, 75. Ungir os pés (Anaxandrides Com. [IV a.C.] 40 <span class=\"greek\">μύρῳ</span> … <span class=\"greek\">ἀλείφει</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πόδας</span> <span class=\"greek\">Καλλιστράτου</span>; Eubulus Com. [IV a.C.] 90, 5f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:46</a>; cf. v. 38c; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:3a</a>; cf. 11:2. Beijar os pés: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:38c</a>, 45.—Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:1</a> <span class=\"greek\">πούς</span> significa claramente perna (cf. Lucian, Zeuxis 4, Pseudomant. 59 <span class=\"greek\">ποὺς</span> <span class=\"greek\">μέχρι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βουβῶνος</span> [virilha]; Achilles Tat. 1, 1, 10; Aëtius p. 86, 2; PGiss 43, 14; PFlor 42, 9 e v. Charles, ICC Rv ad loc.).</p><p class=\"entry-text\">ⓑ Em linguagem figurada especial: o vencido jaz debaixo dos pés do vencedor (Diod S 17, 100, 8 <span class=\"greek\">ῥιφέντος</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">γῆν</span> <span class=\"greek\">ἐπιβὰς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχηλον</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ποδί</span>=[o vencedor] pôs o pé sobre o pescoço de seu inimigo, que fora lançado ao chão) <span class=\"greek\">τιθέναι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐχθροὺς</span> <span class=\"greek\">ὑποκάτω</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ποδῶν</span> <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:36</a>; aqui se cita Ps 109:1; sua redação segundo a LXX é citada mais exatamente como <span class=\"greek\">ὑποπόδιον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ποδῶν</span> <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:13</a>; 10:13; 1 Cl 36:5; B 12:10. Em lugar disso, na mesma citação do Salmo, <span class=\"greek\">τιθ</span>. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> (<span class=\"greek\">αὐτοῦ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:25</a> (Plut., Mor. 1197c <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">τιθ</span>.). <span class=\"greek\">πάντα</span> <span class=\"greek\">ὑπέταξεν</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:22</a>; estas passagens citam Ps 8:7, cuja redação exata na LXX aparece em <span class=\"greek\">ὑποκάτω</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ποδῶν</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:8</a>.—<span class=\"greek\">συντρίψει</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σατανᾶν</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:20</a>.—A terra como escabelo dos pés de Deus (Is 66:1) <span class=\"greek\">ὑποπόδιον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ποδῶν</span> <span class=\"greek\">αὐτοῦ</span> (ou, como na LXX, <span class=\"greek\">μου</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.49\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:49</a>; B 16:2. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:1</a> (sobre a provável alusão polêmica contra Ísis, v. bibliografia citada em EDNT III 144).—Segundo um uso comum também no AT (Eur., Hipp. 661, Or. 1217), os pés representam a pessoa que está em movimento: <span class=\"greek\">οἱ</span> <span class=\"greek\">πόδες</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θαψάντων</span> aqueles que sepultaram <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:9</a>. <span class=\"greek\">ὀξεῖς</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">πόδες</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἐκχέαι</span> <span class=\"greek\">αἷμα</span> são rápidos para derramar sangue <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:15</a> (cf. Is 59:7). <span class=\"greek\">τοῦ</span> <span class=\"greek\">κατευθῦναι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">εἰρήνης</span> para guiar-nos no caminho da paz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.79\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:79</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:15</a> (cf. Is 52:7).</p><p class=\"entry-text\">② Pé de um móvel, pé (assim Aristoph. et al.; Arrian, Anab. 6, 29, 5; SIG 996, 9f; PLond II, 402, verso 27; 30 pp. 10 e 12; POxy 520, 17) Hv 3, 13, 3.</p><p class=\"entry-text\">③ Medida baseada no comprimento do pé humano, pé (Hdt., também inscrições, papiros) Hv 4, 1, 6; 4, 2, 1; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:5</a> v. <span class=\"greek\">βῆμα</span>.—RAC VIII 743–77; BHHW I 505f; B. 243. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρᾶγμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρᾶγμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">πράσσω</span>; Pind., Hdt.+), geralmente ‘algo em que alguém está empenhado’.</p><p class=\"entry-text\">① Aquilo que se faz ou acontece, ato, coisa, acontecimento, ocorrência, assunto (Jos., Ant. 16, 376; Ps.-Clem., Hom. 9, 5; Just., D. 23, 4) <span class=\"greek\">περὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πεπληροφορημένων</span> <span class=\"greek\">πραγμάτων</span> acerca dos acontecimentos que se realizaram <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:1</a> (cf. Jos., Vi. 40 <span class=\"greek\">τ</span>. <span class=\"greek\">ἱστορίαν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πραγμάτων</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">ἀναγράφειν</span>, C. Ap. 1, 47). <span class=\"greek\">τὸ</span> <span class=\"greek\">πρᾶγμα</span> <span class=\"greek\">τοῦτο</span> este ato <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:4</a>. <span class=\"greek\">ἁγνοὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πράγματι</span> inocentes no assunto em discussão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:11</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">δύο</span> <span class=\"greek\">πραγμάτων</span> <span class=\"greek\">ἀμεταθέτων</span> mediante duas coisas imutáveis (isto é, a promessa e o juramento) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:18</a>.</p><p class=\"entry-text\">② Aquilo que deve ser feito, empreendimento, ocupação, tarefa (Appian, Mithrid. 103 §477 <span class=\"greek\">μεγάλα</span> <span class=\"greek\">πράγματα</span>=grandes empreendimentos; Lucian, Nav. 41; Eccl 3:1; TestJob 6:3 <span class=\"greek\">περὶ</span> <span class=\"greek\">πράγματος</span> <span class=\"greek\">ἀναγκαίου</span>) <span class=\"greek\">βιωτικὰ</span> <span class=\"greek\">πράγματα</span> tarefas da vida cotidiana Hv 3, 11, 3; m 5, 2, 2. <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">χρῄζῃ</span> <span class=\"greek\">πράγματι</span> em qualquer empreendimento em que ela necessite de vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:2</a>. <span class=\"greek\">πλεονεκτεῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πράγματι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀδελφόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:6</a> (mas v. 3 abaixo). <span class=\"greek\">ἄξιον</span> <span class=\"greek\">πρᾶγμα</span> uma tarefa digna ISm 11:3.</p><p class=\"entry-text\">③ Assunto ou interesse de qualquer espécie, coisa, questão, negócio (Fgm. Iamb. Adesp. 12 Diehl <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστ</span>’ <span class=\"greek\">ἐμὸν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρ</span>.; Dio Chrys. 13 [7], 53; 16 [33], 36; 19 [36], 18; Ath. 15, 1 <span class=\"greek\">δύο</span> <span class=\"greek\">ὀνόματα</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">πράγματος</span>) <span class=\"greek\">περὶ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">πράγματος</span> acerca de qualquer coisa que seja <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:19</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:1</a>; 11:1 (RTaylor, ET 52, ’40/41, 256–59: ‘assunto’); Hv 3, 4, 1; m 9:10; 10, 2, 3; Hs 5, 6, 6; 9, 29, 2. Pl. Hv 3, 3, 1; 4, 1, 4; 4, 3, 1. <span class=\"greek\">μέγα</span> <span class=\"greek\">π</span>. algo grande Hv 3, 2, 4; cf. Hs 9, 2, 5; <span class=\"greek\">ἔνδοξα</span> <span class=\"greek\">π</span>. Hv 4, 1, 4; <span class=\"greek\">πονηρὸν</span> <span class=\"greek\">π</span>. uma coisa má 1, 1, 8; Hs 5, 1, 5; 7:5; <span class=\"greek\">πᾶν</span> <span class=\"greek\">φαῦλον</span> <span class=\"greek\">π</span>. toda coisa má, tudo que é mau <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:16</a>. <span class=\"greek\">περιγίνεσθαι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">π</span>. dominar a questão Hv 1, 3, 2. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρ</span>. relações, modos de vida, circunstâncias (Diod S 14, 97, 3; 19, 50, 2; 19, 52, 1; 6; Appian, Bell. Civ. 5, 3 §12; Artem. 4, 27; Jos., Bell. 4, 318) <span class=\"greek\">ἐν</span> <span class=\"greek\">παλαιοῖς</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἀναστραφῆναι</span> viver segundo modos antigos, obsoletos IMg 9:1. Também com conotação desfavorável, dificuldades, tribulações (Soph., Aj. 314; X., An. 2, 1, 16; 7, 6, 24, Mem. 2, 7, 2; Socrat., Ep. 3; Diod S 13, 12, 1; 13, 97, 6; Jos., Ant. 13, 7; Just., A II, 4, 1) 1 Cl 1:1 (v. <span class=\"greek\">ἐπιζητέω</span> 1c).—Cf. IMg 5:1; Hv 1, 2, 4.—Provavelmente como eufemismo=relacionamento (sexual ilícito) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:6</a> (cf. Aeschin. 1, 132), mas v. 4.</p><p class=\"entry-text\">④ Questão litigiosa, disputa, processo judicial (X., Mem. 2, 9, 1 e outros; Polyaenus 6, 36; Cyr.-Ins. 54; 67; 123. Frequentemente em papiros; Jos., C. Ap. 2, 177) <span class=\"greek\">πρᾶγμα</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> ter um processo judicial contra alguém (POxy 743, 19 [I a.C.]; 706, 4; BGU 22, 9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:1</a> (LVischer, Die Auslegungsgeschichte von <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:1</a>–11, ’55). Talvez processo judicial <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:6</a> (cf. Ps.-Clemens, Hom. 10, 1).—B. 634. DELG s.v. <span class=\"greek\">πράσσω</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πραγματεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πραγματεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πραγματεύομαι</span>; Hippocr., X., Pla. et al.; papiros, LXX; AscIs 2, 5 [pl.]; Philo; Jos., Ant. 1, 5; 14, 218; empréstimo no vocabulário rabínico), atividade, ocupação, em nossa literatura somente no pl., empreendimentos, negócios, afazeres Hm 10, 1, 4; Hs 9, 20, 1f. <span class=\"greek\">αἱ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βίου</span> <span class=\"greek\">π</span>. os afazeres da vida cotidiana (civil) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:4</a> (Philo, Spec. Leg. 2, 65 <span class=\"greek\">αἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">βίον</span> <span class=\"greek\">π</span>.). <span class=\"greek\">π</span>. <span class=\"greek\">πονηραί</span> Hv 2, 3, 1. Sob perseguição, levando à negação de Cristo v 3, 6, 5; Hs 8, 8, 2. Induzindo as pessoas a mentir m 3:5. Separando dos santos Hs 8, 8, 1.—DELG s.v. <span class=\"greek\">πράσσω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πραγματεύομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πραγματεύομαι</span> (<span class=\"greek\">πρᾶγμα</span>) depoente méd.; 1º aor. <span class=\"greek\">ἐπραγματευσάμην</span> (Hdt.+; inscrições, papiros, LXX, Philo; Jos., Bell. 2, 594, Ant. 4, 149; 16, 180 e outros) ‘conduzir / dedicar-se a um negócio’ (assim Plut., Sull. 462 [17, 2], Cato Min. 788 [59, 3]; PEdg 32 [=Sb 6738], 11 [255 a.C.]; UPZ 106, 5 [99 a.C.]; BGU 246, 8; PLond V, 1674, 84; 1855, 3; Philo, In Flacc. 57), negociar, comerciar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:13</a>.—B. 819. DELG s.v. <span class=\"greek\">πράσσω</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πραθείς, πραθῆναι</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πραθείς</span>, <span class=\"greek\">πραθῆναι</span> v. <span class=\"greek\">πιπράσκω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πραιτώριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πραιτώριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (empréstimo lat.: praetorium. Atestado em grego em inscrições e papiros, v. CWessely, WienerStud 24, 1902, 144; UWilcken, APF 2, 1903, 138; 4, 1908, 116; 121; v. também PPetaus 47, 44; 48, 2; B-D-F §5, 1; Rob. 109), o pretório, originalmente a tenda do pretor no acampamento, com seus arredores. No curso de sua história (esboçada por MDibelius, excurso sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:13</a>), a palavra passou também a designar a residência oficial do governador (IG XIV, 2548 <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἡγεμονικοῦ</span> <span class=\"greek\">πραιτωρίου</span>; SIG 880, 63; BGU 288, 14; POxy 471, 110). Este é o sentido da palavra nos evangelhos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:28ab</a>, 33; 19:9. Mas é questão controvertida se ela se refere ao palácio de Herodes na parte ocidental da cidade (Schürer I 361 com referências a Jos., Bell. 2, 14, 8; 15, 5 e Philo, Leg. 38; REckardt, Das Praetorium des Pilatus: ZDPV 34, 1911, 39–48; Dalman, Orte3 355–63 [trad. ingl. 335–45]; JBlinzler, Der Prozess Jesu3, ’60, 183–86; PBenoit, RB 59, ’52, 531–50, HTR 64, 71, 135–67; RMackowski; Jerusalem, City of Jesus ’80, 102–11; JMurphy-O’Connor, The Holy Land, ed. rev. ’86) ou à fortaleza Antônia a noroeste da área do templo (assim a tradição posterior e SMeistermann, Le Prétoire de Pilate et la forteresse Antonia 1902; CSachsse, ZNW 19, 1920, 34–38; CLattey, JTS 31, 1930, 180–82; HVincent, L’Antonia et le Prétoire: RB 42, ’33, 83–113, Autour du Prétoire: ibid. 46, ’37, 563–70; JFinegan, Archaelogy of the NT ’69, 156–62). Sobre o palácio real hasmoneu como local do pretório de Pilatos, v. BPixner, ZDPV 95, ’79, 65–86, também ABD s.v. ‘Praetorium’ (bibliografia); contra esta identificação antiga, v. Dalman acima. Acerca de um palácio de Herodes GJs 21:2 (códices). Em Cesareia, de qualquer modo, o palácio de Herodes servia de ‘pretório’. Paulo esteve preso <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πραιτωρίῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἡρῴδου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:35</a>. ELohmeyer (Phil 1930, 3; 40f) situa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:13</a> aqui; esta conclusão é avaliada diversamente, dependendo da concepção que se tenha do lugar em que Paulo esteve preso. Se a carta foi escrita de Roma, as palavras <span class=\"greek\">ἐν</span> <span class=\"greek\">ὅλῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πραιτωρίῳ</span> são mais bem entendidas no sentido de em toda a guarda pretoriana (ou imperial) (EHaupt, PEwald, et al.). Se pertence a um encarceramento fora de Roma, <span class=\"greek\">τὸ</span> <span class=\"greek\">πραιτώριον</span> ao lado de <span class=\"greek\">οἱ</span> <span class=\"greek\">λοιποί</span> inclui os que vivem no palácio do governador (v. PFeine [s.v. <span class=\"greek\">Φίλιπποι</span>] p. 72f; 88 e a demais bibliografia ali indicada).—Pauly-W. XXII 2535–37, Suppl. IX 1180f; Kl. Pauly IV 1117; BHHW III 1482; ABD V 322f, 447f. M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πραίφεκτος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πραίφεκτος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Polyb. 6, 26, 5; inscrições [IG XIV, 680, II d.C.; IGR 1, 10]; Lydus, Mag. 2, 6), pessoa nomeada para administrar em função civil ou militar, prefeito (lat. praefectus) <span class=\"greek\">ὁ</span> <span class=\"greek\">πραίφεκτος</span> <span class=\"greek\">ἀτενίζων</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Πέτρῳ</span> o prefeito (da cidade de Roma, Agripa), olhando fixamente para Pedro, (disse) AcPl Ox 849, 12f (Aa I 73, 20). [<span class=\"greek\">τῷ</span>] <span class=\"greek\">προφέκτῳ</span> (em lugar de <span class=\"greek\">πραιφέκτῳ</span>) <span class=\"greek\">Λογ</span>[<span class=\"greek\">γίνῳ</span>] (compartilhando zelosamente a Palavra) com o prefeito (militar) Long[ino] AcPl Ha 9, 18.—Mason 78 (inscrições); Boffo, Iscrizioni p. 219.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πράκτωρ, ορος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πράκτωρ</span>, <span class=\"greek\">ορος</span>, <span class=\"greek\">ὁ</span> (Aeschyl. et al.; Is 3:12), termo técnico que designa certos funcionários, especialmente cobradores de impostos e outros funcionários financeiros (Antiphon et al.; inscrições, papiros [Dssm., B 152=BS 154; BGU 530, 36; O. Wilck. 1599, II d.C.]. Também frequentemente Sb [lista de palavras, seção 8 p. 339]). Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.58\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:58ab</a>, o único lugar em que ocorre em nossa literatura, a palavra se refere a um funcionário do tribunal subordinado às ordens de um juiz, algo como um oficial de justiça ou agente judicial, encarregado de uma prisão de devedores (<span class=\"greek\">πρακτόρειον</span>: OGI 669, 15; 17. Em UPZ 118, 15; 24 <span class=\"greek\">πρ</span>. é o agente judicial; cabe-lhe, depois de proferida a sentença, cobrar [à força, se necessário] dívidas, sob ordens do juiz. O <span class=\"greek\">τοῦ</span> <span class=\"greek\">κριτηρίου</span> <span class=\"greek\">ὑπηρέτης</span> ‘servidor do tribunal’ linha 18 é distinguido dele).—DELG s.v. <span class=\"greek\">πράσσω</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρᾶξις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρᾶξις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πράσσω</span>; Hom.+).</p><p class=\"entry-text\">① Função que implica atividade continuada, atuação, atividade, função <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πρᾶξιν</span> <span class=\"greek\">αὐτοῦ</span> de acordo com sua atividade ou com o que fez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:27</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλη</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">πρᾶξιν</span> os membros não têm todos a mesma função <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:4</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">πράξει</span> <span class=\"greek\">αὐτοῦ</span> Hm 5, 2, 7; cf. 7:1; Hs 4:4.</p><p class=\"entry-text\">② Maneira de conduzir-se, modo de agir, procedimento <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρᾶξις</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">γυναικὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνδρὶ</span> <span class=\"greek\">κεῖται</span> este é o procedimento adequado para a esposa e para o marido Hm 4, 1, 8; cf. 11.</p><p class=\"entry-text\">③ Envolvimento em um projeto que implica planejamento, plano de ação, empreendimento (Jos., Bell. 1, 230, Vi. 271) <span class=\"greek\">περὶ</span> <span class=\"greek\">πράξεώς</span> <span class=\"greek\">τινος</span> acerca de qualquer empreendimento Hm 11:4.</p><p class=\"entry-text\">④ Realização de algum feito, ato, ação, obra</p><p class=\"entry-text\">ⓐ Em geral (Diod S 10, 19, 5=feito; Just., A I, 17, 4 <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἀξίαν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πράξεων</span>) Hm 10, 2, 2 e 4b. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγαθὴ</span> <span class=\"greek\">πρᾶξις</span> 1 Cl 30:7. <span class=\"greek\">μεγάλαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔνδοξοι</span> <span class=\"greek\">πράξεις</span> grandes e gloriosos feitos 19:2.—Aqui também pertence o título de Ac <span class=\"greek\">πράξεις</span> (<span class=\"greek\">ἀποστόλων</span>); cf. 2 Ch 12:15; 13:22; 28:26 e a tradução de Res Gestae Divi Augusti: IGR III, 159 <span class=\"greek\">πράξεις</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δωρεαὶ</span> <span class=\"greek\">Σεβαστοῦ</span> <span class=\"greek\">Θεοῦ</span>; Socrat., Ep. 28, 1 [Malherbe p. 284, 23f] <span class=\"greek\">Ἀντίπατρος</span> … <span class=\"greek\">γράφει</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">Ἑλληνικὰς</span> <span class=\"greek\">πράξεις</span>; Diod S 3, 1, 1 acerca dos primeiros dois livros de Diodoro <span class=\"greek\">ἡ</span> <span class=\"greek\">πρώτη</span> contém as <span class=\"greek\">πράξεις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">βασιλέων</span>; 16, 1, 1 <span class=\"greek\">πόλεων</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">βασιλέων</span> <span class=\"greek\">πράξεις</span>=a história de cidades ou reis; Jos., Ant. 14, 68 <span class=\"greek\">οἱ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">Πομπήιον</span> <span class=\"greek\">πράξεις</span> <span class=\"greek\">ἀναγράψαντες</span>; Tat. 38, 1 <span class=\"greek\">τὰς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">βασιλέων</span> <span class=\"greek\">πράξεις</span>. Também os exemplos em AWikenhauser, Die AG 1921, 94–104: D. antike Praxeis-Lit. O sing., <span class=\"greek\">πρᾶξις</span> (<span class=\"greek\">ἀποστόλων</span>), também atestado, considera os feitos coletivamente, obra.—Para bibliografia sobre Ac, v. EGrässer, TRu 26, ’60, 91–167; também os comentários.</p><p class=\"entry-text\">ⓑ Ato mau ou vergonhoso (Polyb. 2, 7, 9; 2, 9, 2; 4, 71, 6; Diod S 3, 57, 4; 4, 49, 3; 4, 63, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:51</a>; Hm 4, 2, 2. Pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:9</a>; Hm 4, 2, 1.—Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:18</a>, por causa do contexto, é possível que <span class=\"greek\">πρᾶξις</span> seja especificamente um termo técnico para certas práticas mágicas (PGM 4, 1227 <span class=\"greek\">πρᾶξις</span> <span class=\"greek\">γενναία</span> <span class=\"greek\">ἐκβάλλουσα</span> <span class=\"greek\">δαίμονας</span>. Cf. PGM 1, 276; 4, 159; 1317 e frequentemente; Ps.-Clem., Hom. 2, 26; Acta Pilati A 1, 1 [Ea 215, 2]; <span class=\"greek\">πράσσειν</span>=‘praticar magia’ PGM 3, 125).</p><p class=\"entry-text\">⑤ Atividade cotidiana habitual, empreendimento, negócio (assim Aesop, Fab. 236 P.=312 H.//256 Ch//227 H-H.; muito frequentemente em Vett. Val., v. índice; PGM 4, 2366; empréstimo no vocabulário rabínico) pl. Hm 6, 2, 5; 10, 1, 4; Hs 6, 3, 5. <span class=\"greek\">αἱ</span> <span class=\"greek\">βιωτικαὶ</span> <span class=\"greek\">πρ</span>. os afazeres da vida cotidiana Hv 1, 3, 1 (Ps-Lucian, Halc. 5 <span class=\"greek\">αἱ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">βίον</span> <span class=\"greek\">πρ</span>.).</p><p class=\"entry-text\">⑥ Estado de ser, estado, condição, situação (Pind., Hdt. et al.) <span class=\"greek\">τὴν</span> <span class=\"greek\">πρᾶξιν</span>, <span class=\"greek\">ἣν</span> <span class=\"greek\">ἕχουσιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτοῖς</span> Hs 9, 26, 8; também no pl. (Soph., Ant. 1305 <span class=\"greek\">κακαὶ</span> <span class=\"greek\">πράξεις</span>) <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προτέρων</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">πράξεων</span> de sua condição anterior Hv 3, 12, 2. <span class=\"greek\">ἑτέραις</span> <span class=\"greek\">πολλαῖς</span> <span class=\"greek\">πράξεσι</span> <span class=\"greek\">πάσχοντες</span> sofrendo em muitas outras situações Hs 6, 3, 4.—DELG s.v. <span class=\"greek\">πράσσω</span>. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρᾶος</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρᾶος</span> (sem <span class=\"greek\">ι</span> subscrito; v. W-S. §5, 11a; Mlt-H. 84; Mayser 121) v. <span class=\"greek\">πραΰς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πραότης</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πραότης</span> v. <span class=\"greek\">πραΰτης</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρασιά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρασιά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πράσον</span> ‘alho-poró’ [propriamente ‘canteiro de alhos-porós’]; Hom. [<span class=\"greek\">πρασιή</span>] et al.; PTebt 703, 198 [III a.C.: <span class=\"greek\">πρασιά</span>]; BGU 530, 27 [<span class=\"greek\">πρασεά</span>]; Sir 24:31), do sentido lit. ‘parcela de jardim, canteiro’ há apenas um pequeno passo até a expressão figurada <span class=\"greek\">πρασιαὶ</span> <span class=\"greek\">πρασιαί</span> grupo por grupo, representando os grupos de pessoas em contraste com a relva verde <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:40</a> (sobre a força distributiva da repetição, cf. Hs 8, 2, 8 <span class=\"greek\">τάγματα</span> <span class=\"greek\">τάγματα</span> e v. B-D-F §493, 2; Mlt. 97; Rob. 673).—DELG s.v. <span class=\"greek\">πράσον</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0296-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πράσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πράσσω</span> imperf. <span class=\"greek\">ἔπρασσον</span>; fut. <span class=\"greek\">πράξω</span>; 1º aor. <span class=\"greek\">ἔπραξα</span>; perf. <span class=\"greek\">πέπραχα</span>. Pass.: 1º aor. <span class=\"greek\">ἐπράχθην</span>; perf. part. <span class=\"greek\">πεπραγμένος</span> (Hom.+ [a forma ática <span class=\"greek\">πράττω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:7</a> v.l.; 19:36 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:9</a> v.l., cf. Gignac I 151; para inscrições Threatte II 650f]; inscrições, papiros, LXX, EpArist, Philo, Joseph., Test12Patr; Just., D. 35, 7 oposto a <span class=\"greek\">λόγος</span>).</p><p class=\"entry-text\">① Produzir ou realizar algo mediante atividade, trans.</p><p class=\"entry-text\">ⓐ Fazer, realizar (frequentemente empregado sem distinção entre ele próprio e <span class=\"greek\">ποιεῖν</span>, como Diod S 16, 27, 1 <span class=\"greek\">ἔξεστιν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">πράττειν</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">βούλεται</span>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:32</a>; 2:3; IMg 7:1). <span class=\"greek\">τὶ</span> algo <span class=\"greek\">προσέχετε</span> <span class=\"greek\">ἑαυτοῖς</span> … <span class=\"greek\">τί</span> <span class=\"greek\">μέλλετε</span> <span class=\"greek\">πράσσειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:35</a>; <span class=\"greek\">πάντα</span> <span class=\"greek\">πρ</span>. IMg 4; 6:1; cf. 7:1; ITr 2:2 e outros. <span class=\"greek\">πρᾶξιν</span> <span class=\"greek\">πράσσειν</span> (v. também mais abaixo) realizar um feito, fazer algo Hs 5, 2, 11; <span class=\"greek\">τὰ</span> <span class=\"greek\">πνευματικὰ</span> <span class=\"greek\">πρ</span>. fazer coisas espirituais IEph 8:2a. <span class=\"greek\">ἄξια</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μετανοίας</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">πρ</span>. realizar obras condizentes com o arrependimento, agir de maneira condizente etc. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:20</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">δικαιοσύνην</span> 2 Cl 19:3 (cf. Xenophanes 1, 16 Diehl2 <span class=\"greek\">τὰ</span> <span class=\"greek\">δίκαια</span> <span class=\"greek\">πρήσσειν</span>). <span class=\"greek\">εἴτε</span> <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">εἴτε</span> <span class=\"greek\">φαῦλον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:10</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:11</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:9</a>.—Pass. <span class=\"greek\">οὐ</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">γωνίᾳ</span> <span class=\"greek\">πεπραγμένον</span> <span class=\"greek\">τοῦτο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:26</a>.—Principalmente acerca de ações que não são louváveis (TestAbr B 10 p. 115, 8 [Stone p. 78] <span class=\"greek\">εἴ</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἔπραξεν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">νεότητος</span> <span class=\"greek\">αὐτῆς</span>; ApcEsdr 4:24 <span class=\"greek\">μικρὸν</span> <span class=\"greek\">θέλημα</span> <span class=\"greek\">πράξας</span>) fazer, cometer <span class=\"greek\">τὶ</span> algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:23</a>; 23:41a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:32ab</a>; 2:1–3; 7:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:21</a> (<span class=\"greek\">ᾗ</span> por atração em lugar de <span class=\"greek\">ἥν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:21</a>; 1 Cl 35:6; 2 Cl 4:5; 10:5; Hm 3:3; D 1:5 (<span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span> = <span class=\"greek\">περὶ</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">ἅ</span>). <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:2</a> (Herodas 3, 62; cf. 82 <span class=\"greek\">ἔργα</span> <span class=\"greek\">πράσσειν</span>=cometer más obras; <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">πρ</span>. como Jos., Vi. 47). <span class=\"greek\">τὴν</span> <span class=\"greek\">πολυτέλειαν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐθνῶν</span> <span class=\"greek\">πρ</span>. Hs 1:10; <span class=\"greek\">ἄτοπον</span> <span class=\"greek\">τι</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:41b</a> (<span class=\"greek\">ἄτοπος</span> 2). (<span class=\"greek\">τὸ</span>) <span class=\"greek\">κακόν</span> (Pr 13:10 <span class=\"greek\">κακά</span>; Jos., Ant. 19, 193) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:19</a>; 13:4. <span class=\"greek\">τὸ</span> <span class=\"greek\">πονηρόν</span> Hm 10, 2, 4. <span class=\"greek\">πονηρά</span> 2 Cl 8:2; 19:2. <span class=\"greek\">πονηρὰ</span> <span class=\"greek\">ἔργα</span> Hs 6, 3, 5; cf. 6. <span class=\"greek\">πονηρίαν</span> 8, 8, 2. <span class=\"greek\">προπετές</span> <span class=\"greek\">τι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:36</a>. (<span class=\"greek\">τὰ</span>) <span class=\"greek\">φαῦλα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:20</a>; 5:29. <span class=\"greek\">πρᾶξιν</span> <span class=\"greek\">πράσσειν</span> cometer um ato (mau) (<span class=\"greek\">πρᾶξις</span> 4b) Hm 4, 2, 2; 10, 2, 3 (<span class=\"greek\">ᾗ</span> por atração em lugar de <span class=\"greek\">ἥν</span>); pl. Hs 8, 9, 4; 8, 10, 4. <span class=\"greek\">ἄλλα</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">πράσσοντες</span> <span class=\"greek\">ἀνάξια</span> <span class=\"greek\">θεοῦ</span> enquanto fazem certas outras coisas indignas de Deus IEph 7:1. <span class=\"greek\">ἄξιον</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">πράσσειν</span> <span class=\"greek\">τι</span> fazer algo digno de morte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:11</a>, 25; 26:31; pass. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἄξιον</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">πεπραγμένον</span> <span class=\"greek\">αὐτῷ</span> (por ele, B-D-F §191; Rob. 534; cf. Demosth. 29, 1 <span class=\"greek\">τὰ</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">πεπραγμένα</span>; Diod S 17, 1, 2; Appian, Bell. Civ. 3, 44 §180 <span class=\"greek\">τὰ</span> <span class=\"greek\">Καίσαρι</span> <span class=\"greek\">πεπραγμένα</span>; Chariton 2, 5, 8 <span class=\"greek\">πέπρακταί</span> <span class=\"greek\">σοί</span> <span class=\"greek\">τι</span> <span class=\"greek\">δεινόν</span>=um ato terrível foi cometido por ti; Syntipas p. 17, 1 <span class=\"greek\">τὰ</span> <span class=\"greek\">πραχθέντα</span> <span class=\"greek\">μοι</span>; PTebt 23, 8 [119 ou 114 a.C.] <span class=\"greek\">πέπρακταί</span> <span class=\"greek\">σοι</span>; Jos., Ant. 14, 161 <span class=\"greek\">τὰ</span> <span class=\"greek\">Ἡρῴδῃ</span> <span class=\"greek\">πεπραγμένα</span>; Ath. 20, 2 <span class=\"greek\">τὰ</span> <span class=\"greek\">πραχθέντα</span> <span class=\"greek\">αὐτοῖς</span>. Outros exemplos em Mlt-H. 459; Schmid IV 612) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:15</a>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">ἐναντία</span> <span class=\"greek\">πρᾶξαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:9</a> (<span class=\"greek\">ἐναντία</span> <span class=\"greek\">πρ</span>. como X., Cyr. 8, 7, 24). <span class=\"greek\">μηδὲν</span> <span class=\"greek\">πράξῃς</span> <span class=\"greek\">σεαυτῷ</span> <span class=\"greek\">κακόν</span> não faças mal algum a ti mesmo 16:28.—Inácio tem predileção por combinações com <span class=\"greek\">κατά</span> e o ac. <span class=\"greek\">μηδὲν</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐριθείαν</span> <span class=\"greek\">πρ</span>. IPhld 8:2; <span class=\"greek\">κατὰ</span> <span class=\"greek\">θεόν</span> <span class=\"greek\">τι</span> <span class=\"greek\">πρ</span>. 4; <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">τι</span> <span class=\"greek\">πρ</span>. fazer algo no corpo (físico) IEph 8:2b; igualmente 16:2 fazer algo que envolve o físico, isto é, em contraste com a corrupção do evangelho, como fazem os falsos mestres.—Mais no sentido de praticar, ocupar-se de, cuidar de <span class=\"greek\">τὶ</span> algo <span class=\"greek\">τὰ</span> <span class=\"greek\">περίεργα</span> magia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:19</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴδια</span> os próprios assuntos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:11</a> (<span class=\"greek\">ἴδιος</span> 4b e Soph., El. 678 <span class=\"greek\">σὺ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">σαυτῆς</span> <span class=\"greek\">πρᾶσσε</span>; X., Mem. 2, 9, 1 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">πρ</span>.). <span class=\"greek\">τὰ</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">πρ</span>. ocupar-se de muitas coisas Hs 4:5; <span class=\"greek\">νόμον</span> <span class=\"greek\">πρ</span>. observar a lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:25</a>.</p><p class=\"entry-text\">ⓑ Cobrar impostos, direitos, juros (Hdt. et al.; Theophr., Char. 6, 10; inscrições, papiros, LXX; Jos., Ant. 9, 233 e outros) <span class=\"greek\">τὶ</span> algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:23</a>. Com conotação que se aproxima de ‘extorquir’ 3:13 (cf. OGI 519, 22 <span class=\"greek\">τὰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὀφειλόμενα</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">παραπράσσουσιν</span>).</p><p class=\"entry-text\">② Empenhar-se em atividade ou comportar-se de determinada maneira, intrans., agir, comportar-se <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἄγνοιαν</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:17</a>; <span class=\"greek\">ἀπέναντι</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δογμάτων</span> <span class=\"greek\">πρ</span>. agir contrariamente aos decretos 17:7 (oposto a <span class=\"greek\">εὖ</span> <span class=\"greek\">πράσσειν</span>); <span class=\"greek\">καθὰ</span> <span class=\"greek\">πράσσομεν</span> em nossas ações IMg 10:1. <span class=\"greek\">εὖ</span> <span class=\"greek\">πράσσειν</span> agir corretamente, proceder bem (Just., A I, 28, 3 [-<span class=\"greek\">ττ</span>-]; cf. POxy 1067, 3 [III d.C.] <span class=\"greek\">καλῶς</span> <span class=\"greek\">πρ</span>. e Appian, Hann. 2, §3 <span class=\"greek\">πρ</span>. <span class=\"greek\">κακῶς</span>) IEph 4:2; ISm 11:3; provavelmente também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:29</a> por causa do foco no cumprimento das disposições do decreto (cf. a formulação <span class=\"greek\">εὖ</span> <span class=\"greek\">ποίησετε</span> … <span class=\"greek\">ἀποδεχάμενα</span> IMagnMai 91d, 8–10; Danker, Benefactor 311f; v. <span class=\"greek\">εὖ</span> e 3 abaixo).</p><p class=\"entry-text\">③ Experimentar o que está acontecendo, estar, encontrar-se, intrans. (Pind., Hdt.; papiros) <span class=\"greek\">εὖ</span> <span class=\"greek\">πρ</span>. passar bem (v. <span class=\"greek\">εὖ</span> 1), assim talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:29</a> (cf. POxy 120, 27 [IV d.C.]; v. 2 acima; em qualquer das interpretações, prevê-se um efeito positivo sobre os beneficiários, decorrente de sua observância). <span class=\"greek\">ἵνα</span> <span class=\"greek\">εἰδῆτε</span> … <span class=\"greek\">τί</span> <span class=\"greek\">πράσσω</span> para que saibais … como (lit. ‘com respeito a quê’) estou passando <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:21</a> (Soph., Oed. R. 74 <span class=\"greek\">τί</span> <span class=\"greek\">πράσσει</span>; Pla., Tht. 174b; BGU 93, 32 <span class=\"greek\">δήλωσόν</span> <span class=\"greek\">μοι</span>, <span class=\"greek\">τί</span> <span class=\"greek\">ἔπραξας</span>; 821, 8; Jos., Ant. 6, 176; 19, 239).—B. 537f. DELG. Schmidt, Syn. I 397–423. M-M. TW. Sv.</p></section></article>"};
